mapper.select:
WITH EQP_STATUS_INFO AS( SELECT EQP_G,CASE WHEN CHAMBER IS NOT NULL THEN EQP_ID||'.'||CHAMBER ELSE EQP_ID END EQP_ID ,PREV_STATE,PREV_E10_STATE_CODE FROM( SELECT DISTINCT EQP_G,EQP_ID,CASE WHEN LENGTH(CHAMBER)=1 OR LENGTH(CHAMBER)=3 OR CHAMBER IS NULL THEN CHAMBER ELSE REGEXP_REPLACE(CHAMBER, '\d', '') END CHAMBER ,PREV_STATE,PREV_E10_STATE_CODE FROM( SELECT EQP_G ,CASE WHEN INSTR(EQP_ID,'.')>0 THEN SUBSTR(EQP_ID,1,INSTR(EQP_ID,'.')-1) ELSE EQP_ID END EQP_ID ,CASE WHEN INSTR(EQP_ID,'.')>0 THEN SUBSTR(EQP_ID,INSTR(EQP_ID,'.')+1) END CHAMBER ,PREV_STATE,PREV_E10_STATE_CODE FROM PWEB.EQP_ID_STATUS_DAILY WHERE SHIFT_DATE = TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') ))),BASE_INFO AS( SELECT EQP_G,EQP_ID,MODULE,ALARM_CODE,UNIT_ID,UNIT_FLAG,OCCUR_TIME ,EQP_ID ||'.'||UNIT_ID UNIT_LINK1 ,CASE WHEN UNIT_ID LIKE 'CH%' THEN EQP_ID ||'.'||REPLACE(UNIT_ID,'CH','') END UNIT_LINK2 FROM( SELECT C.*,ROW_NUMBER()OVER(PARTITION BY EQP_ID,UNIT_ID ORDER BY OCCUR_TIME DESC)RN FROM( SELECT A.*,B.ALARM_CODE ,SUBSTR(ALARM_TEXT2,1,INSTR(ALARM_TEXT2,'_')-1)UNIT_ID ,SUBSTR(ALARM_TEXT2,INSTR(ALARM_TEXT2,'_')+1)UNIT_FLAG ,OCCUR_TIME FROM( SELECT EQP_G,EQP_ID,MODULE FROM PWEB.EQP_ID_USE_STD WHERE ACTIVE_FLAG = 'Y' AND MODULE = #{module,jdbcType=VARCHAR} AND EQP_G = #{eqpG,jdbcType=VARCHAR} )A JOIN A1MFG.V_PB11_EVENT_ALARM B ON A.EQP_ID =B.EQPID )C)WHERE RN = 1 ),KEY_COMMENT_INFO AS( SELECT KEY1 EQP_ID,KEY2 UNIT_ID,KEY3 OCCUR_TIME,F_COMMENT FROM PWEB.COMMENT_SUMMARY WHERE FUNCTION_NAME ='EQP_UNIT_MONITOR' ) SELECT EQP_G,EQP_ID,MODULE,ALARM_CODE,UNIT_ID,UNIT_FLAG,OCCUR_TIME,EQP_STATUS,EQP_E10,UNIT_STATUS,UNIT_E10 ,UNIT_JUDGE,F_COMMENT FROM( SELECT EQP_G,EQP_ID,MODULE,ALARM_CODE,UNIT_ID,UNIT_FLAG,OCCUR_TIME,EQP_STATUS,EQP_E10,UNIT_STATUS,UNIT_E10 ,CASE WHEN UNIT_FLAG = 'OFFLINE' AND NVL(UNIT_STATUS,EQP_STATUS) NOT IN('SDT','UDT','NST') THEN 'Y' ELSE 'N' END UNIT_JUDGE,F_COMMENT FROM( SELECT A.EQP_G,A.EQP_ID,A.MODULE,A.ALARM_CODE,A.UNIT_ID,A.UNIT_FLAG,A.OCCUR_TIME ,B.PREV_STATE EQP_E10 ,B.PREV_E10_STATE_CODE EQP_STATUS ,NVL(C.PREV_STATE,D.PREV_STATE ) UNIT_E10 ,NVL(C.PREV_E10_STATE_CODE,D.PREV_E10_STATE_CODE) UNIT_STATUS ,E.F_COMMENT FROM BASE_INFO A LEFT JOIN EQP_STATUS_INFO B ON A.EQP_ID = B.EQP_ID LEFT JOIN EQP_STATUS_INFO C ON A.UNIT_LINK1 = C.EQP_ID LEFT JOIN EQP_STATUS_INFO D ON A.UNIT_LINK2 = D.EQP_ID LEFT JOIN KEY_COMMENT_INFO E ON A.EQP_ID = E.EQP_ID AND A.UNIT_ID = E.UNIT_ID AND TO_CHAR(A.OCCUR_TIME,'YYYY-MM-DD HH24:MI:SS') = E.OCCUR_TIME ))WHERE 1=1
AND UNIT_JUDGE = #{unitJudge,jdbcType=VARCHAR}
AND UNIT_FLAG = #{unitFlag,jdbcType=VARCHAR}
ORDER BY OCCUR_TIME DESC
